cssCode:
.wipe-container { height: 200vh; width: 100%; position: relative; }
.wipe-panel {
  position: sticky; top: 0; height: 100vh; width: 100%;
  display: flex; align-items: center; justify-content: center; overflow: hidden;
}
.wipe-overlay {
  position: absolute; bottom: 0; left: 0; width: 100%; height: 0%;
  background: linear-gradient(to top, #7928ca, #ff007f);
  border-radius: 50% 50% 0 0 / 10% 10% 0 0;
  transition: height 0.1s linear, border-radius 0.1s linear;
  display: flex; align-items: center; justify-content: center;
  color: #fff; font-size: 30px; font-weight: bold; font-family: sans-serif;
  overflow: hidden;
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:transparent;';

const wrap = document.createElement('div');
wrap.className = 'wipe-container';

const panel = document.createElement('div');
panel.className = 'wipe-panel';
panel.innerHTML = '<span style="color:#555; font-family:sans-serif;">SCROLL DOWN ↓</span>';

const overlay = document.createElement('div');
overlay.className = 'wipe-overlay';
overlay.innerText = 'NEXT SECTION ✨';

panel.appendChild(overlay);
wrap.appendChild(panel);
c.appendChild(wrap);

c.addEventListener('scroll', () => {
  const max = c.scrollHeight - c.clientHeight;
  const p = c.scrollTop / max;

  overlay.style.height = `${p * 100}%`;
  // લિક્વિડ ગોળાઈ ધીમે ધીમે સીધી થશે
  const curve = Math.max(0, 20 - p * 20); 
  overlay.style.borderRadius = `${curve}% ${curve}% 0 0 / ${curve * 2}% ${curve * 2}% 0 0`;
});
